from typing import Optional

@override
async def estimate_tokens(
    self, messages: Messages, tool_specs: Optional[list[ToolSpec]] = None, system_prompt: Optional[str] = None
) -> int:
    """Estimate token count for the given input before sending to model."""
    # Using tiktoken to count tokens for OpenAI model
    encoder = tiktoken.encoding_for_model(self.get_config().get("model_id", "gpt-4"))
    text = ""
    if system_prompt:
        text += system_prompt + "\n"
    for msg in messages:
        role = msg.get("role", "")
        content_list = msg.get("content", [])
        text += role + ": "
        for block in content_list:
            if "text" in block:
                text += block["text"] + "\n"
            elif "toolUse" in block:
                # Approximate tokens for toolUse block input as json string
                import json
                text += json.dumps(block["toolUse"]["input"]) + "\n"
    return len(encoder.encode(text))
EOF"}

